function routePrefill(){
  const outer=new URLSearchParams(String(globalThis.location?.search||'').replace(/^\?/u,''));
  const embedded=outer.get('gh_route');
  const query=embedded?.includes('?')?embedded.slice(embedded.indexOf('?')+1):String(globalThis.location?.search||'').replace(/^\?/u,'');
  const params=new URLSearchParams(query),interval=Number(params.get('interval')||360),ruleType=params.get('ruleType')||'any';
  const incoming={...emptyForm,url:params.get('url')||'',title:params.get('title')||'',condition:params.get('condition')||'',ruleType:ruleTypes.includes(ruleType)?ruleType:'any',ruleValue:params.get('ruleValue')||'',intervalMinutes:intervalOptions.includes(interval)?interval:360};
  const bounded=(name,max,pattern)=>{const value=(params.get(name)||'').trim();return value&&value.length<=max&&(!pattern||pattern.test(value))?value:'';},topicId=bounded('topicId',100,/^[A-Za-z0-9_-]+$/u),analysisType=bounded('analysis',40),metricKey=bounded('metricKey',80,/^[a-z0-9][a-z0-9._-]*$/u),methodVersion=bounded('methodVersion',80,/^[a-z0-9][a-z0-9._-]*$/u),derivedMetricId=bounded('derivedMetricId',100,/^[A-Za-z0-9_-]+$/u),metricViewId=bounded('metricViewId',100,/^[A-Za-z0-9_-]+$/u),dimensionKey=bounded('dimensionKey',40,/^[A-Za-z0-9][A-Za-z0-9._-]*$/u),dimensionValue=bounded('dimensionValue',120),subject=bounded('subject',240),predicateKey=bounded('predicateKey',80,/^[a-z0-9][a-z0-9._-]*$/u),scopeKey=bounded('scopeKey',40,/^[A-Za-z0-9][A-Za-z0-9._-]*$/u),scopeValue=bounded('scopeValue',120),trendInterval=bounded('trendInterval',10),date=value=>{const raw=params.get(value)||'';return raw&&!Number.isNaN(new Date(raw).getTime())?new Date(raw).toISOString():'';},pairPattern=/^([a-z0-9][a-z0-9._-]{0,79}):([a-z0-9][a-z0-9._-]{0,79})$/u,matrixMetrics=params.getAll('metric').slice(0,9).map(value=>value.match(pairPattern)).filter(Boolean).map(match=>({metricKey:match[1],methodVersion:match[2]}));
  const analysis=topicId?{topicId,analysisType:agentAnalysisTypes.includes(analysisType)?analysisType:'',metricKey,methodVersion,metrics:matrixMetrics,derivedMetricId,metricViewId,dimensionKey,dimensionValue,subject,predicateKey,scopeKey,scopeValue,interval:['day','week','month'].includes(trendInterval)?trendInterval:'month',from:date('from'),to:date('to')}:null;
  if(incoming.url)return{watch:incoming,analysis};
  try{const saved=JSON.parse(globalThis.sessionStorage?.getItem(pendingStorageKey)||'null');return{watch:saved?.url?{...incoming,...saved}:incoming,analysis};}catch{return{watch:incoming,analysis};}
}
function suggestedTitle(value){try{return new URL(value).hostname.replace(/^www\./u,'');}catch{return '';}}
function formatTime(value,locale){if(!value)return '—';try{return new Intl.DateTimeFormat(locale,{dateStyle:'medium',timeStyle:'short'}).format(new Date(value));}catch{return value;}}
function formatDelta(value){const number=Number(value||0);return number>0?`+${number}`:String(number);}
function formatBytes(value,locale){const bytes=Math.max(0,Number(value)||0),units=['B','KiB','MiB','GiB'];let amount=bytes,index=0;while(amount>=1024&&index<units.length-1){amount/=1024;index+=1;}return `${new Intl.NumberFormat(locale,{maximumFractionDigits:index?1:0}).format(amount)} ${units[index]}`;}
