function billingPeriodDefaults(){const now=new Date(),end=new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),1)),start=new Date(Date.UTC(end.getUTCFullYear(),end.getUTCMonth()-1,1));return{provider:'deepseek-search',periodStart:start.toISOString().slice(0,10),periodEnd:end.toISOString().slice(0,10),statementBillableRequests:'',statementCostUsd:'',sourceReference:'',note:''};}
function selectAgentReports(items){const selected=[];for(const kind of ['run-summary','calendar-week-summary','calendar-month-summary','weekly-summary','monthly-summary']){const report=items.find(item=>item.kind===kind);if(report&&!selected.some(item=>item.id===report.id))selected.push(report);if(selected.length===3)break;}return selected;}
function formatMetricValue(value,unit,locale){if(value===null||value===undefined)return '—';const formatted=typeof value==='number'&&Number.isFinite(value)?new Intl.NumberFormat(locale,{maximumFractionDigits:6}).format(value):String(value);return `${formatted}${unit?` ${unit}`:''}`;}
function formatFactValue(fact,locale){if(!fact)return '';return `${fact.dimensionLabel} · ${fact.predicateLabel}: ${formatMetricValue(fact.value,fact.unit,locale)} · ${fact.direction}`;}
