  useEffect(()=>{let active=true;setAssessment(null);setState('loading');api.getResearchTopicStorageAssessment(topicId).then(({data})=>{if(active){setAssessment(data);setState('ready');}}).catch(()=>{if(active){setAssessment(null);setState('error');}});return()=>{active=false;};},[api,refreshKey,topicId]);
