  useEffect(()=>{let active=true;setState('loading');setError('');api.listResearchTopicBillingReconciliations(topicId).then(({data})=>{if(active){setItems(Array.isArray(data)?data:[]);setState('ready');}}).catch(()=>{if(active){setItems([]);setState('error');}});return()=>{active=false;};},[api,topicId]);
