  const review=async(item,decision)=>{const note=(reviewNotes[item.id]||'').trim();if(note.length<10)return;setState(`review:${item.id}`);setError('');try{await api.reviewResearchTopicBillingReconciliation(topicId,item.id,{decision,note});setReviewNotes(current=>({...current,[item.id]:''}));await reload();setState('ready');}catch(caught){setError(caught.message||t('tools.changeRadar.topic.billingReviewFailed'));setState('ready');}};
  return <details className="change-radar__billing"><summary><span><strong>{t('tools.changeRadar.topic.billingTitle')}</strong><small>{t('tools.changeRadar.topic.billingLead')}</small></span><span>{items.length}</span></summary><p>{t('tools.changeRadar.topic.billingSafety')}</p><form onSubmit={create}><div><label>{t('tools.changeRadar.topic.operationsProvider')}<input required maxLength="80" value={form.provider} onChange={event=>setForm(current=>({...current,provider:event.target.value}))}/></label><label>{t('tools.changeRadar.topic.billingPeriodStart')}<input required type="date" value={form.periodStart} onChange={event=>setForm(current=>({...current,periodStart:event.target.value}))}/></label><label>{t('tools.changeRadar.topic.billingPeriodEnd')}<input required type="date" value={form.periodEnd} onChange={event=>setForm(current=>({...current,periodEnd:event.target.value}))}/></label><label>{t('tools.changeRadar.topic.operationsBillable')}<input required type="number" min="0" max="1000000000" value={form.statementBillableRequests} onChange={event=>setForm(current=>({...current,statementBillableRequests:event.target.value}))}/></label><label>{t('tools.changeRadar.topic.billingStatementCost')}<input required type="number" min="0" max="9000000" step="0.000001" value={form.statementCostUsd} onChange={event=>setForm(current=>({...current,statementCostUsd:event.target.value}))}/></label><label>{t('tools.changeRadar.topic.billingReference')}<input maxLength="240" value={form.sourceReference} onChange={event=>setForm(current=>({...current,sourceReference:event.target.value}))}/></label></div><textarea required minLength="10" maxLength="1000" value={form.note} onChange={event=>setForm(current=>({...current,note:event.target.value}))} placeholder={t('tools.changeRadar.topic.billingNote')}/><button type="submit" disabled={state==='saving'}>{state==='saving'?t('tools.changeRadar.topic.billingSaving'):t('tools.changeRadar.topic.billingCreate')}</button></form>{state==='loading'&&<p>{t('tools.changeRadar.topic.operationsLoading')}</p>}{state==='error'&&<p className="error-text">{t('tools.changeRadar.topic.billingFailed')}</p>}{error&&<p className="error-text">{error}</p>}{items.length>0&&<ol>{items.map(item=><li key={item.id}><header><div><strong>{item.provider}</strong><small>{formatTime(item.periodStartAt,locale)} → {formatTime(item.periodEndAt,locale)}</small></div>{item.latestReview&&<span className={`change-radar__status is-${item.latestReview.decision==='disputed'?'important':'accepted'}`}>{t(`tools.changeRadar.topic.billingDecision.${item.latestReview.decision}`)}</span>}</header><dl><div><dt>{t('tools.changeRadar.topic.billingStatement')}</dt><dd>{item.statement.billableRequests} · {formatUsdMicros(item.statement.costUsdMicros,locale)}</dd></div><div><dt>{t('tools.changeRadar.topic.billingLedger')}</dt><dd>{item.ledger.billableRequests} · {formatUsdMicros(item.ledger.costUsdMicros,locale)}</dd></div><div><dt>{t('tools.changeRadar.topic.billingDifference')}</dt><dd>{item.difference.billableRequests>0?'+':''}{item.difference.billableRequests} · {formatSignedUsdMicros(item.difference.costUsdMicros,locale)}</dd></div></dl><small>{item.sourceReference||'—'} · SHA-256 {item.inputSha256}</small><p>{item.note}</p>{item.latestReview&&<p>{item.latestReview.note}</p>}<textarea minLength="10" maxLength="1000" value={reviewNotes[item.id]||''} onChange={event=>setReviewNotes(current=>({...current,[item.id]:event.target.value}))} placeholder={t('tools.changeRadar.topic.billingReviewNote')}/><div><button type="button" disabled={(reviewNotes[item.id]||'').trim().length<10||state===`review:${item.id}`} onClick={()=>review(item,'acknowledged')}>{t('tools.changeRadar.topic.billingAcknowledge')}</button><button type="button" disabled={(reviewNotes[item.id]||'').trim().length<10||state===`review:${item.id}`} onClick={()=>review(item,'disputed')}>{t('tools.changeRadar.topic.billingDispute')}</button></div></li>)}</ol>}</details>;
