  useEffect(()=>{let active=true;setState('loading');Promise.all([api.getResearchTopicQualitySummary(topicId),api.listResearchTopicQualitySamples(topicId,{limit:50})]).then(([{data:summaryData},{data:sampleData}])=>{if(active){setSummary(summaryData);setSamples(Array.isArray(sampleData)?sampleData:[]);setState('ready');}}).catch(()=>{if(active){setSummary(null);setSamples([]);setState('error');}});return()=>{active=false;};},[api,refreshKey,topicId]);
