  const review=async(sample,decision)=>{const note=(notes[sample.id]||'').trim();if(note.length<10)return;setState(`review:${sample.id}`);try{await api.reviewResearchTopicQualitySample(topicId,sample.id,{decision,note});setNotes(current=>({...current,[sample.id]:''}));await reload();await onChanged?.();setState('ready');}catch{setState('error');}};
