  const review=async(item,decision)=>{const note=(notes[item.id]||'').trim(),matchedEventId=matches[item.id]||null;if(note.length<10||(decision==='detected'&&!matchedEventId))return;setState(`review:${item.id}`);setError('');try{await api.reviewResearchTopicExternalBenchmarkCase(topicId,item.id,{decision,note,...(decision==='detected'?{matchedEventId}:{})});setNotes(current=>({...current,[item.id]:''}));setMatches(current=>({...current,[item.id]:''}));await reload();setState('ready');}catch(caught){setError(caught.message||t('tools.changeRadar.topic.benchmarkReviewFailed'));setState('ready');}};
